/* ============================================================
   journey-walk.js  — SPEC PSEUDOCODE (not the final module)
   ============================================================ */

import { gsap, ScrollTrigger, reducedMotion } from '../scroll.js';
import { TILE } from './cutefantasy.js';
import { STOPS, PATH_LENGTH, pointAt, stopAnchor } from './journey.js';

/* ---- constants: one block, all tunable ---- */
const SPEED_R = 1.6;        // screen px the map moves per px scrolled
const STRIDE  = 0.25;       // tiles per walk frame
const ENTER_R = 4.5, EXIT_R = 6.0;   // banner window, tiles
const MIN_SHOW = 450;       // ms a card cannot be pulled before
const FLING   = 10;         // tiles/frame above which nothing mounts
const MIN_W   = 640;
const WALK_ROW = { down:3, up:5, left:4, right:4 };
const IDLE_ROW = { down:0, up:2, left:1, right:1 };

/* ---- 1. the scroll -> distance table ---------------------- */

function buildRamps(stageH, zoom) {
  const ppt = TILE * zoom / SPEED_R;      // = 10 * zoom
  const dwell = 0.40 * stageH, ease = 0.18 * stageH;
  const ramps = []; let s = 0, d = 0;

  const travel = (to) => {
    const tiles = to - d;
    if (tiles <= 0) return;
    const px = tiles * ppt + ease;              // ease pays for the soft ends
    const k  = clamp(0.06, ease / (2 * px), 0.5);
    ramps.push({ kind:'travel', s0:s, s1:s+px, d0:d, d1:to, cdf: buildCdf(k) });
    s += px; d = to;
  };

  for (const stop of STOPS) {
    travel(stop.at);
    ramps.push({ kind:'dwell', s0:s, s1:s+dwell, d0:d, d1:d, stop });
    s += dwell;
  }
  travel(PATH_LENGTH);
  return { ramps, total: s };
}

// trapezoid speed profile -> normalised distance CDF, 24 samples, built once
function buildCdf(k) {
  const sm = t => t<=0?0 : t>=1?1 : t*t*(3-2*t);
  const v  = t => sm(t/k) * sm((1-t)/k);
  const N = 24, c = [0];
  for (let i=1;i<=N;i++) c.push(c[i-1] + v((i-0.5)/N));
  return c.map(x => x / c[N]);              // c[0]=0, c[N]=1, monotone
}
const applyCdf = (cdf,u) => lerpTable(cdf, clamp(0,u,1));

function distanceAt(px) {                   // binary search, ramps are monotone
  const r = ramps[indexFor(px)];
  if (r.kind === 'dwell') return { d: r.d0, ramp: r };
  const u = (px - r.s0) / (r.s1 - r.s0);
  return { d: r.d0 + (r.d1 - r.d0) * applyCdf(r.cdf, u), ramp: r };
}

/* ---- 2. init ---------------------------------------------- */

export async function initJourney() {
  const stage = qs('#journeyStage'), canvas = qs('#journeyCanvas'),
        list  = qs('#experienceList');
  if (!stage || !canvas || !list) return;
  if (reducedMotion || innerWidth < MIN_W) return;   // the <ol> IS the section

  const map = await buildMap();   // {ground, props, tall[], w:544, h:1664} at 1x, ONCE
  list.classList.add('u-sr-only');   // hidden visually, still crawlable + in a11y tree
  canvas.setAttribute('aria-hidden','true');
  stage.hidden = false;

  let zoom = 0, Z = 0, stageW = 0, stageH = 0, ramps = [], total = 0;
  let scrollPx = 0, prevD = 0, camX = 0, camY = 0, leadY = 0.5;
  let current = null, held = false, active = false;

  function measure() {
    stageW = stage.clientWidth; stageH = stage.clientHeight;
    zoom = clamp(2, Math.round(stageH / (TILE * 15)), 4);   // integer
    const dpr = Math.min(2, Math.floor(devicePixelRatio) || 1);  // integer
    Z = zoom * dpr;                                          // integer scale
    canvas.width = stageW*dpr; canvas.height = stageH*dpr;
    ctx.imageSmoothingEnabled = false;
    ({ ramps, total } = buildRamps(stageH, zoom));
  }

  ScrollTrigger.create({
    trigger: stage, start: 'top top', end: () => '+=' + total,
    pin: true, anticipatePin: 1, invalidateOnRefresh: true,
    onRefreshInit: measure,
    onUpdate: self => { scrollPx = self.progress * total; },   // store ONLY
    onToggle: self => { active = self.isActive; },
  });
  gsap.ticker.add(frame);      // same loop Lenis drives -> one render per frame

/* ---- 3. the frame ----------------------------------------- */

  function frame(time, deltaMs) {
    if (!active || document.hidden) return;
    const dt = Math.min(deltaMs, 50) / 1000;
    const { d, ramp } = distanceAt(scrollPx);
    const dd = d - prevD;                       // signed tiles this frame
    const back  = dd < -0.001;
    const still = ramp.kind === 'dwell' || Math.abs(dd) < 0.004;

    // facing: chord, not point — pointAt().dir flips exactly on a vertex
    const a = pointAt(d - 0.4), b = pointAt(d + 0.4);
    let dir = Math.abs(b.y-a.y) >= Math.abs(b.x-a.x)
      ? (b.y > a.y ? 'down' : 'up') : (b.x > a.x ? 'right' : 'left');
    if (back) dir = OPPOSITE[dir];
    if (still && ramp.stop) dir = ramp.stop.side < 0 ? 'left' : 'right'; // face the door

    // sprite frame: pure function of d — reverses, freezes, cannot drift
    const row = still ? IDLE_ROW[dir] : WALK_ROW[dir];
    const col = still ? Math.floor(time / 160) % 6
                      : mod(Math.floor(d / STRIDE), 6);
    const flip = dir === 'left';                 // side rows face right; verify in tiles.html

    // camera: leads in the direction of travel, never centres, never lags
    const p = pointAt(d);
    const footX = p.x*TILE + TILE/2, footY = p.y*TILE + TILE;
    const anchor = still ? 0.50 : dir==='down' ? 0.42 : dir==='up' ? 0.58 : 0.50;
    if (!held) leadY += (anchor - leadY) * (1 - Math.exp(-dt/0.35));
    camY = clamp(0, footY*Z - stageH*leadY, map.h*Z - stageH);

    if (map.w*Z <= stageW) camX = -(stageW - map.w*Z)/2;      // fits: centre, no pan
    else {
      const sx = footX*Z - camX, dz = stageW*0.18;
      const want = sx < stageW/2 - dz ? footX*Z - (stageW/2 - dz)
                 : sx > stageW/2 + dz ? footX*Z - (stageW/2 + dz) : camX;
      camX = clamp(0, camX + (want-camX)*(1-Math.exp(-dt/0.25)), map.w*Z - stageW);
    }
    const ox = Math.round(camX), oy = Math.round(camY);   // integer device px, draw only

    blit(map.ground, ox, oy); blit(map.props, ox, oy);
    drawShadow(footX*Z - ox, footY*Z - oy);
    drawPlayer(row, col, flip, footX*Z - ox, footY*Z - oy);
    for (const t of map.tall) if (t.baseY > footY) reblit(t, ox, oy);  // y-sort

    updateBanner(d, dd, ox, oy);
    prevD = d;
  }

/* ---- 4. the banner ---------------------------------------- */

  function updateBanner(d, dd, ox, oy) {
    if (Math.abs(dd) > FLING) { drop(current, true); current = null; held = false; return; }

    let want = null;
    for (const s of STOPS) {
      const r = Math.abs(d - s.at);
      const last = s === STOPS[STOPS.length-1];
      if (r < ENTER_R) want = s;                                   // mount
      else if (current?.stop === s && (r < EXIT_R                  // hysteresis
               || (last && d > s.at))) want = s;                   // final card holds
    }

    if (want !== current?.stop) {
      if (current) {
        const shown = performance.now() - current.shownAt;
        drop(current, want && shown < MIN_SHOW);  // hard cut only if crowded out early
        current = null;
      }
      if (want) {
        const el = cardFrom(qs(`#experienceList li[data-stop="${want.id}"]`));
        stage.appendChild(el);
        requestAnimationFrame(() => el.classList.add('is-in'));  // 180ms fade + 8px rise
        current = { stop: want, el, shownAt: performance.now() };
      }
    }

    held = !!current;                       // freezes leadY while a card is anchored
    if (current) {
      if (stageW < 900) return;             // narrow: fixed bottom sheet, no anchoring
      const A = stopAnchor(current.stop);
      const x = A.col*TILE*Z - ox + (current.stop.side < 0 ? -CARD_W - 12 : 96*Z + 12);
      const y = A.row*TILE*Z - oy - CARD_H;
      current.el.style.transform =
        `translate3d(${clamp(12, x, stageW-CARD_W-12)}px,${clamp(12, y, stageH-CARD_H-12)}px,0)`;
    }
  }

  function drop(c, hard) {
    if (!c) return;
    if (hard) { c.el.remove(); return; }
    c.el.classList.remove('is-in');                 // 220ms fade-out
    c.el.addEventListener('transitionend', () => c.el.remove(), { once:true });
  }

  addEventListener('sa:languagechange', () => {
    if (current) current.el.replaceWith(cardFrom(/* re-read the li */));
  });
}
